/* =====================================================================
   sounds.js — SIGAMOS sound effects + background music
   ---------------------------------------------------------------------
   All sounds here are the actual files you uploaded (base64-embedded,
   same pattern as the card images).

   WHAT PLAYS WHEN:
     Sound.pageForward() — choosing Reseña / Examen, opening Mensajitos or the mistakes list (page-forward-single-chime)
     Sound.pageBack()    — "← Inicio" / "← Cerrar" / every trip back to the main menu       (page-back-chime)
     Sound.next()        — moving forward to the next flashcard            (arrow-whoosh + hard-pop + cooking-bell-ding)
     Sound.correct()     — right quiz answer                               (happy-bell-alert)
     Sound.wrong()       — wrong quiz answer                               (kids-cartoon-close-bells)
     Sound.service()     — "Continuar" after a wrong answer                (service-bell)
     Sound.finishCelebration() — finishing the WHOLE deck (Mexican music + cheering)
     Sound.startBackgroundMusic() — beautiful-dream loop, first tap anywhere

     Letter ("Mensajitos" envelope):
     Sound.startLetterMusic() / stopLetterMusic() — Araw-Araw (Ben&Ben piano cover).
                            Pauses the background music + celebration while the
                            letter is open and restores the background music after.
     Sound.envelopeOpen() — flap opens                       (mixkit paper-slide,        1.09s)
     Sound.paperOut()     — paper taken out / paper unfolds  (mixkit single-book-paging, 2.61s)
     Sound.letterTurn()   — turning the letter around        (mixkit page-turn-single,   0.45s)
     The letter animations in index.html (LETTER_T) are timed to these lengths.

     Examen / Challenge Mode:
     Sound.countdown()   — Friday Night Funkin "3, 2, 1, Go!" (beats at 0.6 / 1.24 / 1.8 / 2.4 s)
     Sound.startSadMusic() / stopSadMusic() — Volver Volver (Vicente Fernández), used on the
                            "try again" result page only (pauses the background music)
     Sound.stopResultAudio() — stops the celebration + sad music when leaving a result page
     Synthesized (no file supplied): Sound.tick(level) 0=slow 1=fast 2=last-30s, Sound.alarm()
                            (Time's-up), Sound.boom() (Challenge Mode intro), Sound.locked().
   ===================================================================== */
(function(){
const SND_HAPPY_BELL   = "data:audio/wav;base64,";
const SND_CARTOON_BELL = "data:audio/wav;base64,";
const SND_SERVICE_BELL = "data:audio/wav;base64,";
const SND_COOKING_BELL = "data:audio/wav;base64,";
const SND_MEXICAN      = "data:audio/mpeg;base64,";
const SND_FNAF_CHEER   = "data:audio/mpeg;base64,";
const SND_BG_MUSIC     = "data:audio/mpeg;base64,";
const SND_WHOOSH       = "data:audio/wav;base64,";
const SND_POP          = "data:audio/wav;base64,";
const SND_PAGE_FWD     = "data:audio/wav;base64,";
const SND_PAGE_BACK    = "data:audio/wav;base64,";
const SND_ARAW         = "data:audio/mpeg;base64,";
const SND_PAPER_SLIDE  = "data:audio/wav;base64,";
const SND_BOOK_PAGING  = "data:audio/wav;base64,";
const SND_PAGE_TURN    = "data:audio/wav;base64,";
const SND_FNF_COUNT    = "data:audio/mpeg;base64,";
const SND_VOLVER       = "data:audio/mpeg;base64,";

  // ---- SFX players -------------------------------------------------
  // Each source is decoded once into a cached <audio> element and then
  // cloned per play, so rapid taps overlap instead of cutting each other
  // off and there's no re-decoding lag on every tap.
  const cache = {};
  function playOnce(dataUri, volume) {
    try {
      const base = cache[dataUri] || (cache[dataUri] = (() => { const a = new Audio(dataUri); a.preload = "auto"; return a; })());
      const a = base.cloneNode(true);
      a.volume = volume == null ? 1 : volume;
      a.play().catch(() => {}); // ignore autoplay-block errors
      return a;
    } catch (e) { return null; }
  }
  function later(fn, ms) { setTimeout(fn, ms); }

  // Paper clips currently playing (so they can be cut when the letter closes).
  let paperLive = [];
  function playPaper(uri, vol) {
    const a = playOnce(uri, vol);
    if (a) { paperLive.push(a); a.onended = () => { paperLive = paperLive.filter(x => x !== a); }; }
  }

  // Shared background-music element so we can start/stop/adjust one
  // instance instead of stacking new ones.
  let bgMusic = null;
  let bgStarted = false;
  let bgPausedForLetter = false;
  let bgPausedForSad = false;
  let sadMusic = null;
  let ctx = null;
  function actx() {
    try {
      ctx = ctx || new (window.AudioContext || window.webkitAudioContext)();
      if (ctx.state === "suspended") ctx.resume();
      return ctx;
    } catch (e) { return null; }
  }
  let letterMusic = null;
  let celebration = [];

  window.Sound = {
    correct: () => playOnce(SND_HAPPY_BELL, 0.9),
    wrong: () => playOnce(SND_CARTOON_BELL, 0.9),
    service: () => playOnce(SND_SERVICE_BELL, 0.9),

    // Page navigation chimes.
    pageForward: () => playOnce(SND_PAGE_FWD, 0.9),
    pageBack: () => playOnce(SND_PAGE_BACK, 0.9),

    // Moving forward one flashcard: arrow-whoosh, then the pop and the
    // cooking-bell-ding a beat behind it so all three are audible.
    next: () => {
      playOnce(SND_WHOOSH, 0.8);
      later(() => playOnce(SND_POP, 0.7), 110);
      later(() => playOnce(SND_COOKING_BELL, 0.8), 200);
    },

    // Only ever called once per finished deck (see finishStackEnding()).
    finishCelebration: () => {
      celebration = [playOnce(SND_MEXICAN, 0.9), playOnce(SND_FNAF_CHEER, 0.9)].filter(Boolean);
    },

    // FNF "3, 2, 1, Go!" — 3.1s long.
    countdown: () => playOnce(SND_FNF_COUNT, 1),

    // Volver Volver on the "try again" page: only this plays (no Mexican
    // music / cheer), background music is paused while it plays.
    startSadMusic: () => {
      try {
        if (bgMusic && !bgMusic.paused) { bgMusic.pause(); bgPausedForSad = true; }
        if (!sadMusic) { sadMusic = new Audio(SND_VOLVER); sadMusic.loop = true; }
        sadMusic.currentTime = 0; sadMusic.volume = 0.85;
        sadMusic.play().catch(() => {});
      } catch (e) { /* ignore */ }
    },
    stopSadMusic: () => {
      try { if (sadMusic) { sadMusic.pause(); sadMusic.currentTime = 0; } } catch (e) {}
      if (bgPausedForSad && bgMusic) { bgMusic.play().catch(() => {}); }
      bgPausedForSad = false;
    },
    stopCelebration: () => {
      celebration.forEach(a => { try { a.pause(); } catch (e) {} });
      celebration = [];
    },
    stopResultAudio: () => { window.Sound.stopCelebration(); window.Sound.stopSadMusic(); },

    // ---- synthesized sounds (Web Audio) -------------------------------
    // Clock tick: level 0 = soft/slow, 1 = "half time" faster, 2 = last 30s (louder).
    tick: (level) => {
      const a = actx(); if (!a) return;
      const t = a.currentTime, o = a.createOscillator(), g = a.createGain();
      o.type = "square"; o.frequency.value = level === 2 ? 1500 : (level === 1 ? 1150 : 900);
      const vol = level === 2 ? 0.32 : (level === 1 ? 0.16 : 0.09);
      g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(vol, t + 0.004);
      g.gain.exponentialRampToValueAtTime(0.0001, t + 0.07);
      o.connect(g).connect(a.destination); o.start(t); o.stop(t + 0.09);
    },
    // Time's-up alarm: alternating loud beeps for ~3s.
    alarm: () => {
      const a = actx(); if (!a) return;
      const t0 = a.currentTime;
      for (let i = 0; i < 12; i++) {
        const t = t0 + i * 0.25, o = a.createOscillator(), g = a.createGain();
        o.type = "sawtooth"; o.frequency.value = i % 2 ? 880 : 1180;
        g.gain.setValueAtTime(0.0001, t); g.gain.linearRampToValueAtTime(0.35, t + 0.02);
        g.gain.setValueAtTime(0.35, t + 0.16); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.23);
        o.connect(g).connect(a.destination); o.start(t); o.stop(t + 0.25);
      }
    },
    // Explosion for the Challenge Mode intro: noise burst + low thump.
    boom: () => {
      const a = actx(); if (!a) return;
      const t = a.currentTime, n = Math.floor(a.sampleRate * 1.4);
      const buf = a.createBuffer(1, n, a.sampleRate), d = buf.getChannelData(0);
      for (let i = 0; i < n; i++) d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / n, 2.2);
      const src = a.createBufferSource(); src.buffer = buf;
      const lp = a.createBiquadFilter(); lp.type = "lowpass"; lp.frequency.setValueAtTime(2400, t); lp.frequency.exponentialRampToValueAtTime(140, t + 1.2);
      const g = a.createGain(); g.gain.value = 0.9;
      src.connect(lp).connect(g).connect(a.destination); src.start(t);
      const o = a.createOscillator(), og = a.createGain();
      o.type = "sine"; o.frequency.setValueAtTime(110, t); o.frequency.exponentialRampToValueAtTime(30, t + 0.9);
      og.gain.setValueAtTime(0.9, t); og.gain.exponentialRampToValueAtTime(0.0001, t + 1.0);
      o.connect(og).connect(a.destination); o.start(t); o.stop(t + 1.05);
    },
    // Short dull "thunk" for a locked envelope.
    locked: () => {
      const a = actx(); if (!a) return;
      const t = a.currentTime, o = a.createOscillator(), g = a.createGain();
      o.type = "triangle"; o.frequency.setValueAtTime(190, t); o.frequency.exponentialRampToValueAtTime(70, t + 0.16);
      g.gain.setValueAtTime(0.5, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.2);
      o.connect(g).connect(a.destination); o.start(t); o.stop(t + 0.22);
    },

    // Starts the looping background track at 40% volume. Safe to call
    // repeatedly — only actually starts it once. Call this from a
    // click handler (e.g. the first tap on the home screen) since
    // browsers block audio that isn't triggered by a user gesture.
    startBackgroundMusic: () => {
      if (bgStarted) return;
      bgStarted = true;
      try {
        bgMusic = new Audio(SND_BG_MUSIC);
        bgMusic.loop = true;
        bgMusic.volume = 0.4;
        bgMusic.play().catch(() => { bgStarted = false; });
      } catch (e) { bgStarted = false; }
    },

    // Letter music: Araw-Araw plays (looped) from the moment the envelope
    // is tapped until the letter is closed. Everything else musical is
    // hushed meanwhile so the songs don't fight each other.
    startLetterMusic: () => {
      try {
        celebration.forEach(a => { try { a.pause(); } catch (e) {} });
        celebration = [];
        if (bgMusic && !bgMusic.paused) { bgMusic.pause(); bgPausedForLetter = true; }
        if (!letterMusic) { letterMusic = new Audio(SND_ARAW); letterMusic.loop = true; }
        letterMusic.currentTime = 0;
        letterMusic.volume = 0.75;
        letterMusic.play().catch(() => {});
      } catch (e) { /* ignore */ }
    },
    stopLetterMusic: () => {
      try { if (letterMusic) { letterMusic.pause(); letterMusic.currentTime = 0; } } catch (e) {}
      if (bgPausedForLetter && bgMusic) { bgMusic.play().catch(() => {}); }
      bgPausedForLetter = false;
    },

    // Letter sounds (see header for the lengths the animations are timed to).
    envelopeOpen: () => playPaper(SND_PAPER_SLIDE, 0.9),
    paperOut: () => playPaper(SND_BOOK_PAGING, 0.9),
    letterTurn: () => playPaper(SND_PAGE_TURN, 0.9),
    // Cuts any letter sound still playing (used when the letter is closed).
    stopPaper: () => {
      paperLive.forEach(a => { try { a.pause(); } catch (e) {} });
      paperLive = [];
    },
  };
})();
